<template>
  <el-card v-if="modules.length" shadow="never" class="result-card">
    <template #header>
      <h3 class="header-font section-title">评分详情</h3>
    </template>
    <div class="modules-grid">
      <article
        v-for="(module, index) in modules"
        :key="module.name"
        class="module-card"
        :class="`tone-${index % 4}`"
      >
        <div class="module-head">
          <div class="module-title">
            <span>{{ module.name }}</span>
            <div class="title-meta">
              <el-tag size="small" effect="light" class="level-tag">{{ module.level }}</el-tag>
            </div>
          </div>
        </div>
        <div class="aspect-list">
          <div v-for="aspect in module.aspects" :key="aspect.name" class="aspect-item">
            <div class="aspect-head">
              <span>{{ aspect.name }}</span>
              <el-tag :type="getLevelTagType(aspect.level)" size="small" class="level-tag">{{
                aspect.level
              }}</el-tag>
            </div>
            <p>{{ aspect.comment }}</p>
          </div>
        </div>
      </article>
    </div>
  </el-card>
</template>

<script setup lang="ts">
import type { ModuleData, ScoreLevel } from '@/types/essay'

defineProps<{
  modules: ModuleData[]
}>()

function getLevelTagType(level: ScoreLevel): 'success' | 'warning' | 'danger' | 'info' {
  switch (level) {
    case 'A':
      return 'success'
    case 'B':
      return 'warning'
    case 'C':
      return 'danger'
    default:
      return 'info'
  }
}
</script>

