<template>
  <el-card shadow="never" class="result-card">
    <template #header>
      <div class="bench-head">
        <h3 class="header-font section-title">文章对比</h3>
        <el-radio-group v-model="localMode" size="small">
          <el-radio-button label="split">并排对比</el-radio-button>
          <el-radio-button label="diff">修改痕迹</el-radio-button>
          <el-radio-button label="optimized">仅看修改后</el-radio-button>
        </el-radio-group>
      </div>
    </template>

    <!-- 并排对比模式 -->
    <div v-if="localMode === 'split'" class="split-view">
      <div class="split-panel">
        <div class="panel-title">原文</div>
        <div ref="leftPanelRef" class="panel-content" @scroll="onLeftScroll">
          <p v-for="(para, idx) in originalParagraphs" :key="`o-${idx}`">{{ para }}</p>
        </div>
      </div>
      <div class="split-panel">
        <div class="panel-title">修改后</div>
        <div ref="rightPanelRef" class="panel-content" @scroll="onRightScroll">
          <p v-for="(para, idx) in optimizedParagraphs" :key="`n-${idx}`">{{ para }}</p>
        </div>
      </div>
    </div>

    <!-- 修改痕迹模式（方案A：使用结构化 Blocks 渲染） -->
    <div v-else-if="localMode === 'diff'" class="diff-view">
      <div class="legend">
        <span><i class="dot delete"></i> 删除</span>
        <span><i class="dot insert"></i> 新增</span>
      </div>
      <div class="diff-content">
        <!-- 使用结构化 Blocks 渲染 -->
        <template v-if="hasStructuredBlocks">
          <diff-paragraph v-for="(block, idx) in diffBlocks" :key="`block-${idx}`" :block="block" />
        </template>
        <!-- 降级方案：使用简单段落对比 -->
        <template v-else>
          <p v-for="(para, idx) in fallbackDiffParagraphs" :key="`fallback-${idx}`" v-html="para" />
        </template>
      </div>
    </div>

    <!-- 仅看修改后模式 -->
    <div v-else class="optimized-view">
      <div class="panel-content">
        <p v-for="(para, idx) in optimizedParagraphs" :key="`f-${idx}`">{{ para }}</p>
      </div>
    </div>
  </el-card>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { DiffBlock } from '@/types/essay'
import DiffParagraph from './DiffParagraph.vue'

const props = defineProps<{
  modelValue: 'split' | 'diff' | 'optimized'
  originalContent: string
  optimizedContent: string
  diffHtml?: string // 方案A：已废弃，保留兼容
  diffData?: {
    changes?: unknown[]
    blocks?: DiffBlock[]
  } | null
}>()

const emit = defineEmits<{
  'update:modelValue': [value: 'split' | 'diff' | 'optimized']
}>()

const localMode = ref<'split' | 'diff' | 'optimized'>(props.modelValue)
const leftPanelRef = ref<HTMLElement | null>(null)
const rightPanelRef = ref<HTMLElement | null>(null)
const syncLock = ref(false)

watch(
  () => props.modelValue,
  (v) => {
    localMode.value = v
  }
)

watch(localMode, (v) => emit('update:modelValue', v))

// 段落分割
const originalParagraphs = computed(() => splitParas(props.originalContent || ''))
const optimizedParagraphs = computed(() => splitParas(props.optimizedContent || ''))

// 方案A：从 diffData 获取结构化 Blocks
const diffBlocks = computed<DiffBlock[]>(() => {
  return props.diffData?.blocks || []
})

// 是否有结构化 Blocks
const hasStructuredBlocks = computed(() => {
  return diffBlocks.value.length > 0
})

// 降级方案：简单段落对比（当没有 Blocks 时使用）
const fallbackDiffParagraphs = computed(() => {
  const leftParas = originalParagraphs.value
  const rightParas = optimizedParagraphs.value
  const max = Math.max(leftParas.length, rightParas.length)
  if (max === 0) return ['<p>暂无内容</p>']

  const chunks: string[] = []
  for (let i = 0; i < max; i++) {
    const l = leftParas[i] || ''
    const r = rightParas[i] || ''

    if (!l && r) {
      chunks.push(`<p><ins>${escapeHtml(r)}</ins></p>`)
      continue
    }
    if (l && !r) {
      chunks.push(`<p><del>${escapeHtml(l)}</del></p>`)
      continue
    }
    if (l === r) {
      chunks.push(`<p>${escapeHtml(l)}</p>`)
      continue
    }

    // 简单的前后缀匹配
    const prefixLen = commonPrefixLen(l, r)
    const suffixLen = commonSuffixLen(l.slice(prefixLen), r.slice(prefixLen))
    const prefix = l.slice(0, prefixLen)
    const oldMid = l.slice(prefixLen, l.length - suffixLen)
    const newMid = r.slice(prefixLen, r.length - suffixLen)
    const suffix = l.slice(l.length - suffixLen)

    chunks.push(
      `<p>${escapeHtml(prefix)}<del>${escapeHtml(oldMid)}</del><ins>${escapeHtml(
        newMid
      )}</ins>${escapeHtml(suffix)}</p>`
    )
  }
  return chunks
})

// 工具函数
function splitParas(input: string): string[] {
  return (input || '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/\/n/g, '\n')
    .split(/\n{2,}/)
    .map((v) => v.trim())
    .filter(Boolean)
}

function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function commonPrefixLen(a: string, b: string): number {
  const max = Math.min(a.length, b.length)
  let i = 0
  while (i < max && a[i] === b[i]) i += 1
  return i
}

function commonSuffixLen(a: string, b: string): number {
  const max = Math.min(a.length, b.length)
  let i = 0
  while (i < max && a[a.length - 1 - i] === b[b.length - 1 - i]) i += 1
  return i
}

function syncScroll(from: HTMLElement | null, to: HTMLElement | null): void {
  if (!from || !to || syncLock.value) return
  const fromRange = from.scrollHeight - from.clientHeight
  const toRange = to.scrollHeight - to.clientHeight
  if (fromRange <= 0 || toRange <= 0) return
  syncLock.value = true
  const ratio = from.scrollTop / fromRange
  to.scrollTop = ratio * toRange
  window.requestAnimationFrame(() => {
    syncLock.value = false
  })
}

function onLeftScroll() {
  syncScroll(leftPanelRef.value, rightPanelRef.value)
}

function onRightScroll() {
  syncScroll(rightPanelRef.value, leftPanelRef.value)
}
</script>

