<template>
  <div class="essay-editor">
    <el-form ref="formRef" :model="form" :rules="rules" label-width="90px" hide-required-asterisk>
      <!-- 题面：作文材料和要求 -->
      <el-form-item label="题面" prop="prompt">
        <el-input
          v-model="form.prompt"
          type="textarea"
          :rows="4"
          placeholder="请输入作文材料、题目要求或阅读材料..."
        />
      </el-form-item>

      <!-- 作文类型 -->
      <el-form-item label="类型">
        <el-select
          v-model="form.essay_type"
          filterable
          allow-create
          clearable
          default-first-option
          placeholder="请输入作文类型"
          style="width: 100%"
        >
          <el-option label="议论文" value="议论文" />
          <el-option label="记叙文" value="记叙文" />
          <el-option label="应用文" value="应用文" />
          <el-option label="说明文" value="说明文" />
          <el-option label="散文" value="散文" />
          <el-option label="其他" value="其他" />
        </el-select>
      </el-form-item>

      <!-- 作文标题 -->
      <el-form-item label="标题" prop="title">
        <el-input v-model="form.title" placeholder="请输入作文标题" />
      </el-form-item>

      <!-- 作文内容 -->
      <el-form-item label="正文" prop="content_text">
        <div class="essay-upload-wrap">
          <el-upload
            class="essay-upload"
            v-model:file-list="fileList"
            :auto-upload="false"
            :limit="5"
            :show-file-list="false"
            :on-change="handleFileChange"
            :disabled="uploadLoading"
            accept=".docx,.doc,.png,.jpg,.jpeg,.webp,.pdf,.md,.txt"
            drag
          >
            <el-icon class="el-icon--upload"><upload-filled /></el-icon>
            <div class="el-upload__text">将文件拖到此处，或<em>点击上传</em></div>
            <template #tip>
              <div class="el-upload__tip">
                {{
                  uploadLoading
                    ? '正在识别中...'
                    : '支持 Word、图片、PDF、MD、TXT，单文件不超过 10MB，最多 5 个文件'
                }}
              </div>
            </template>
          </el-upload>
          <div v-if="fileList.length" class="essay-file-list">
            <div v-for="f in fileList" :key="f.uid" class="essay-file-item">
              <el-icon><document /></el-icon>
              <span class="essay-file-name">{{ f.name }}</span>
              <el-button type="primary" link @click="handleFileRemove(f)">删除</el-button>
            </div>
          </div>
        </div>
        <el-input
          v-model="form.content_text"
          type="textarea"
          :rows="15"
          placeholder="或直接在此输入正文内容，不超过 1500 字"
          style="margin-top: var(--spacing-md)"
        />
      </el-form-item>
    </el-form>
  </div>
</template>

<script setup lang="ts">
import { ref, reactive } from 'vue'
import { UploadFilled, Document } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import type { UploadFile } from 'element-plus'
import type { FormInstance, FormRules } from 'element-plus'
import { extractTextFromFile } from '@/utils/fileParse'
import { extractTextByOCR } from '@/api/ocr'

const WORD_EXT = /\.(docx?|doc)$/i
const IMAGE_EXT = /\.(png|jpe?g|webp)$/i
const PDF_EXT = /\.pdf$/i
const TEXT_EXT = /\.(md|txt)$/i
const FILE_MAX_SIZE = 10 * 1024 * 1024 // 10MB，统一限制
const FILE_MAX_COUNT = 5

const emit = defineEmits<{
  (e: 'update:content', value: string): void
  (e: 'update:file', value: File | null): void
}>()

const formRef = ref<FormInstance>()

interface FormState {
  prompt: string
  essay_type: string
  title: string
  content_text: string
}

const form = reactive<FormState>({
  prompt: '', // 题面/材料要求
  essay_type: '', // 作文类型（议论文/记叙文等）
  title: '', // 作文标题（学生自拟）
  content_text: '', // 作文正文
})

const rules: FormRules = {
  content_text: [{ required: true, message: '请输入作文内容', trigger: 'blur' }],
}

const fileList = ref<UploadFile[]>([])
const uploadLoading = ref(false)

async function handleFileChange(file: UploadFile) {
  if (!file.raw) return
  if (fileList.value.length > FILE_MAX_COUNT) {
    ElMessage.error(`最多上传 ${FILE_MAX_COUNT} 个文件`)
    fileList.value = fileList.value.filter((f) => f.uid !== file.uid)
    return
  }
  const name = file.raw.name
  if (file.raw.size > FILE_MAX_SIZE) {
    ElMessage.error('单文件不能超过 10MB')
    fileList.value = fileList.value.filter((f) => f.uid !== file.uid)
    return
  }
  if (WORD_EXT.test(name)) {
    try {
      const text = await extractTextFromFile(file.raw)
      appendContent(text)
    } catch {
      ElMessage.error('Word 解析失败，请确认文件格式')
      fileList.value = fileList.value.filter((f) => f.uid !== file.uid)
    }
    return
  }
  if (TEXT_EXT.test(name)) {
    try {
      const text = await extractTextFromFile(file.raw)
      appendContent(text)
    } catch {
      ElMessage.error('MD/TXT 读取失败')
      fileList.value = fileList.value.filter((f) => f.uid !== file.uid)
    }
    return
  }
  if (IMAGE_EXT.test(name)) {
    uploadLoading.value = true
    try {
      const text = await extractTextByOCR(file.raw)
      appendContent(text)
    } catch {
      ElMessage.error('服务繁忙，请稍后重试，或减小文件、书写清晰后再上传')
      fileList.value = fileList.value.filter((f) => f.uid !== file.uid)
    } finally {
      uploadLoading.value = false
    }
    return
  }
  if (PDF_EXT.test(name)) {
    uploadLoading.value = true
    try {
      const text = await extractTextByOCR(file.raw)
      appendContent(text)
    } catch {
      ElMessage.error('服务繁忙，请稍后重试，或减小文件、书写清晰后再上传')
      fileList.value = fileList.value.filter((f) => f.uid !== file.uid)
    } finally {
      uploadLoading.value = false
    }
    return
  }
  ElMessage.error('仅支持 Word、图片、PDF、MD、TXT')
  fileList.value = fileList.value.filter((f) => f.uid !== file.uid)
}

function appendContent(text: string) {
  const sep = form.content_text.trim() ? '\n\n' : ''
  form.content_text = (form.content_text.trim() + sep + text).trim()
  emit('update:content', form.content_text)
  emit('update:file', fileList.value[0]?.raw ?? null)
}

function handleFileRemove(file: UploadFile) {
  fileList.value = fileList.value.filter((f) => f.uid !== file.uid)
  emit('update:file', fileList.value.length ? (fileList.value[0]?.raw ?? null) : null)
}

defineExpose({
  form,
  formRef,
  validate: () =>
    formRef.value
      ?.validate()
      .then(() => true)
      .catch(() => false),
  clear: () => {
    form.prompt = ''
    form.essay_type = ''
    form.title = ''
    form.content_text = ''
    fileList.value = []
    formRef.value?.clearValidate()
  },
})
</script>

