<template>
  <!-- 相同段落：正常显示 -->
  <p v-if="block.type === 'equal'" class="diff-para equal">
    {{ block.new_text || block.old_text }}
  </p>

  <!-- 删除段落：红色删除线 -->
  <p v-else-if="block.type === 'delete'" class="diff-para delete">
    <del>{{ block.old_text }}</del>
  </p>

  <!-- 新增段落：绿色下划线/背景 -->
  <p v-else-if="block.type === 'insert'" class="diff-para insert">
    <ins>{{ block.new_text }}</ins>
  </p>

  <!-- 修改段落：行内对比 -->
  <p v-else-if="block.type === 'modify'" class="diff-para modify">
    <template v-if="hasInlineDiff">
      <template v-for="(change, idx) in block.inline_diff" :key="idx">
        <span v-if="change.type === 'eq'" class="text-equal">{{ change.text }}</span>
        <del v-else-if="change.type === 'del'" class="text-delete">{{ change.text }}</del>
        <ins v-else-if="change.type === 'ins'" class="text-insert">{{ change.text }}</ins>
      </template>
    </template>
    <template v-else>
      <!-- 降级：整段显示修改 -->
      <del class="text-delete">{{ block.old_text }}</del>
      <ins class="text-insert">{{ block.new_text }}</ins>
    </template>
  </p>
</template>

<script setup lang="ts">
import { computed } from 'vue'
import type { DiffBlock } from '@/types/essay'

const props = defineProps<{
  block: DiffBlock
}>()

const hasInlineDiff = computed(() => {
  return props.block.inline_diff && props.block.inline_diff.length > 0
})
</script>

<style scoped>
.diff-para {
  line-height: 1.85;
  margin-bottom: 12px;
  text-indent: 2em;
  color: var(--result-text-primary);
}

/* 删除段落 */
.delete {
  background: #fee2e2;
}

.delete del {
  color: #b91c1c;
  text-decoration-thickness: 2px;
}

/* 新增段落 */
.insert {
  background: #dcfce7;
}

.insert ins {
  color: #166534;
  text-decoration: none;
  font-weight: 500;
}

/* 修改段落 - 行内样式 */
.modify .text-delete {
  background: #fee2e2;
  color: #b91c1c;
  padding: 2px 2px;
  border-radius: 3px;
  text-decoration-thickness: 2px;
}

.modify .text-insert {
  background: #dcfce7;
  color: #166534;
  padding: 2px 2px;
  border-radius: 3px;
  text-decoration: none;
  font-weight: 500;
}

.modify .text-equal {
  /* 相同部分无特殊样式 */
}
</style>
