<template>
  <div class="correction-result">
    <ResultHero :summary-data="summaryData" />
    <ResultModules :modules="modules" />
    <ResultStats :stats="computedStats" />
    <ResultWorkbench
      v-model="viewMode"
      :original-content="props.originalContent || ''"
      :optimized-content="props.correction?.opt_work || ''"
      :diff-data="diffData"
    />
  </div>
</template>

<script setup lang="ts">
import { ref, computed } from 'vue'
import type { Correction, SummaryData, ModuleData, DiffData } from '@/types/essay'
import ResultHero from '@/components/Essay/result/ResultHero.vue'
import ResultModules from '@/components/Essay/result/ResultModules.vue'
import ResultStats from '@/components/Essay/result/ResultStats.vue'
import ResultWorkbench from '@/components/Essay/result/ResultWorkbench.vue'

const props = defineProps<{
  correction: Correction | null
  originalContent?: string
}>()

const viewMode = ref<'split' | 'diff' | 'optimized'>('diff')

// 解析结构化数据
const summaryData = computed<SummaryData | null>(() => {
  if (!props.correction) return null
  if (props.correction.summary_data) {
    return props.correction.summary_data
  }
  // 尝试从 raw_json 解析
  if (props.correction.raw_json?.summary) {
    return props.correction.raw_json.summary as SummaryData
  }
  return null
})

const modules = computed<ModuleData[]>(() => {
  if (!props.correction) return []
  if (props.correction.modules) {
    return props.correction.modules
  }
  // 尝试从 raw_json 解析
  if (props.correction.raw_json?.modules) {
    return props.correction.raw_json.modules as ModuleData[]
  }
  return []
})

const diffData = computed<DiffData | null>(() => {
  if (!props.correction) return null
  if (props.correction.diff_data) {
    return props.correction.diff_data
  }
  // 尝试从 raw_json 解析
  if (props.correction.raw_json?.diff_data) {
    return props.correction.raw_json.diff_data as DiffData
  }
  return null
})

// 根据 blocks 实时计算统计
// 显示：删除字数、新增字数、总字数、段落数
const computedStats = computed(() => {
  const blocks = diffData.value?.blocks

  // 计算总字数（从修改后的文章内容）
  const totalWords = countWords(props.correction?.opt_work || props.originalContent || '')

  if (!blocks || blocks.length === 0) {
    // 没有 blocks 时，回退到简单计算
    const paragraphs = countParagraphs(props.correction?.opt_work || props.originalContent || '')
    return {
      words_deleted: 0,
      words_inserted: 0,
      total_words: totalWords,
      paragraphs: paragraphs,
    }
  }

  let deleted = 0
  let inserted = 0
  let paragraphs = 0

  for (const block of blocks) {
    switch (block.type) {
      case 'delete':
        // 删除段落：统计删除字数，不计入段落数
        deleted += countWords(block.old_text || '')
        break
      case 'insert':
        // 新增段落：统计新增字数，计入段落数
        inserted += countWords(block.new_text || '')
        paragraphs++
        break
      case 'modify':
        // 修改段落：统计增删字数，计入段落数
        paragraphs++
        if (block.inline_diff && block.inline_diff.length > 0) {
          for (const inline of block.inline_diff) {
            if (inline.type === 'del') {
              deleted += countWords(inline.text)
            } else if (inline.type === 'ins') {
              inserted += countWords(inline.text)
            }
          }
        }
        break
      case 'equal':
        // 相同段落：计入段落数
        paragraphs++
        break
    }
  }

  return {
    words_deleted: deleted,
    words_inserted: inserted,
    total_words: totalWords,
    paragraphs: paragraphs,
  }
})

// 字数统计函数（与后端一致：中文字符 + 英文单词）
function countWords(text: string): number {
  if (!text) return 0
  let count = 0
  for (const char of text) {
    // 中文字符范围
    if (char >= '\u4e00' && char <= '\u9fff') {
      count++
    }
  }
  // 英文单词数（简单统计）
  const englishWords = text.match(/[a-zA-Z]+/g) || []
  count += englishWords.length
  return count
}

// 段落统计函数
function countParagraphs(text: string): number {
  if (!text) return 0
  // 按双换行分割（与后端 splitParagraphs 逻辑一致）
  const rawParas = text.split(/\n{2,}/)
  let count = 0
  for (const p of rawParas) {
    if (p.trim()) count++
  }
  return count || 1 // 至少1段
}
</script>

<style scoped>
.correction-result {
  display: flex;
  flex-direction: column;
  gap: var(--result-gap);
}
@media (max-width: 768px) {
  .correction-result {
    gap: 12px;
  }
}
</style>
