import request from '@/utils/request'

/** OCR 识别图片中的文字，返回纯文本（视觉接口较慢，单独延长超时） */
export async function extractTextByOCR(file: File): Promise<string> {
  const formData = new FormData()
  formData.append('file', file)
  const res = await request.post<{ text: string }>('/ocr', formData, {
    timeout: 35000,
    skipGlobalErrorToast: true,
  })
  return res.data.text
}
